function formatNumber(value) {
  return Number(value || 0).toLocaleString("zh-CN");
}

function money(value) {
  return `¥${formatNumber(value)}`;
}

function shortTitle(product) {
  const text = `${product.name || ""} ${product.fullName || ""}`;
  const match = text.match(/【([^】]+)】/);
  return match ? `【${match[1]}】` : product.code;
}

function listItems(items) {
  return (items || []).map((item) => `<li>${item}</li>`).join("");
}

function renderFilters() {
  const categories = [...new Set(products.map((product) => product.category).filter(Boolean))];
  filterRow.innerHTML = [ALL_FILTER, ...categories]
    .map(
      (category) => `
        <button class="filter-button ${category === activeFilter ? "is-active" : ""}" data-filter="${category}" type="button">
          ${category}
        </button>
      `
    )
    .join("");
}

function visibleProducts() {
  const keyword = searchInput.value.trim().toLowerCase();
  return products.filter((product) => {
    const matchFilter = activeFilter === ALL_FILTER || product.category === activeFilter;
    const haystack = `${product.id} ${product.code} ${product.name} ${product.fullName} ${product.category}`.toLowerCase();
    return matchFilter && haystack.includes(keyword);
  });
}

function renderProductList() {
  const visible = visibleProducts();
  if (!visible.length) {
    productList.innerHTML = `<div class="empty-state">没有匹配的商品</div>`;
    return;
  }

  if (!visible.some((product) => product.id === activeProduct?.id)) {
    activeProduct = visible[0];
    renderCard(activeProduct);
  }

  productList.innerHTML = visible
    .map(
      (product) => `
        <button class="product-item ${product.id === activeProduct?.id ? "is-active" : ""}" data-id="${product.id}" type="button">
          <img class="product-thumb" src="${product.image}" alt="" loading="lazy" />
          <span class="mobile-short-title">${shortTitle(product)}</span>
          <span class="product-item-content">
            <strong>${product.name}</strong>
            <span class="product-item-tags">
              <span>${product.code}</span>
              <span>${product.category}</span>
              <span>${money(product.price)}</span>
              <span>近7天 ${formatNumber(product.sevenDaySales)}</span>
            </span>
          </span>
        </button>
      `
    )
    .join("");
}

function renderScriptBlocks(script) {
  return (script || [])
    .map(
      (block) => `
        <div class="script-block">
          <div class="script-heading">
            <strong>${block.title}</strong>
          </div>
          <ul>${listItems(block.lines)}</ul>
        </div>
      `
    )
    .join("");
}

function renderQuickNotes(notes) {
  return (notes || [])
    .map(
      ([label, text]) => `
        <div class="quick-note">
          <strong>${label}</strong>
          <span>${text}</span>
        </div>
      `
    )
    .join("");
}

function renderStockTable(sizeStock) {
  const sizes = (sizeStock || []).filter(([, qty]) => qty !== null && qty !== undefined);
  if (!sizes.length) return "";
  return `
    <div class="stock-table" aria-label="尺码库存">
      <div class="stock-row stock-size-row">
        ${sizes.map(([size]) => `<span>${size}</span>`).join("")}
      </div>
      <div class="stock-row stock-count-row">
        ${sizes.map(([, qty]) => `<span>${formatNumber(qty)}</span>`).join("")}
      </div>
    </div>
  `;
}

function renderQuickNotesForProduct(product) {
  const notes = product.quickNotes || [];
  const nonStockNotes = notes.filter(([label]) => label !== "库存信息");
  const hasOddNonStockNotes = nonStockNotes.length % 2 === 1;

  return notes
    .map(([label, text], index) => {
      const content = label === "库存信息" ? renderStockTable(product.sizeStock) : `<span>${text}</span>`;
      const isLastOddNote =
        label !== "库存信息" &&
        hasOddNonStockNotes &&
        notes.slice(index + 1).every(([nextLabel]) => nextLabel === "库存信息");
      return `
        <div class="quick-note ${label === "库存信息" ? "stock-note" : ""} ${isLastOddNote ? "wide-note" : ""}">
          <strong>${label}</strong>
          ${content}
        </div>
      `;
    })
    .join("");
}

function renderFabricInfo(fabric) {
  const info = fabric || {};
  const hasMaterial = info.main && info.main !== "系统暂未返回材质成份";
  return `
    <div class="fabric-card">
      <div class="fabric-title">
        <strong>面料信息</strong>
        <span>${hasMaterial ? "已同步BPF材质成份" : "后续按商品编码更新"}</span>
      </div>
      <p class="fabric-main">${info.main || "系统暂未返回材质成份"}</p>
    </div>
  `;
}

function renderCard(product) {
  if (!product) {
    currentName.textContent = "-";
    currentMeta.innerHTML = "";
    cardPreview.innerHTML = `<div class="empty-state">暂无商品数据</div>`;
    return;
  }

  currentName.textContent = product.name;
  currentMeta.innerHTML = `
    <span class="pill hot">${product.tags?.[0] || product.saleMode}</span>
    <span class="pill">${product.saleMode}</span>
    <span class="pill">库存 ${formatNumber(product.stock)}</span>
    <span class="pill">近7天 ${formatNumber(product.sevenDaySales)}</span>
  `;

  cardPreview.innerHTML = `
    <div class="card-top">
      <div class="image-panel">
        <img src="${product.image}" alt="${product.name}" />
        ${renderFabricInfo(product.fabric)}
      </div>
      <div class="summary-panel">
        <div class="card-heading-row">
          <div class="card-code">${product.code}</div>
          <div class="product-tags">
            ${(product.tags || []).map((tag) => `<span class="pill ${tag === "爆旺" ? "hot" : ""}">${tag}</span>`).join("")}
          </div>
        </div>
        <h2 class="card-title">${product.name}</h2>
        <p class="one-liner">${product.positioning}</p>
        <div class="metric-grid">
          <div class="metric"><small>直播价</small><b>${money(product.price)}</b></div>
          <div class="metric"><small>品类</small><b>${product.category}</b></div>
          <div class="metric"><small>库存</small><b>${formatNumber(product.stock)}</b></div>
          <div class="metric"><small>近7天</small><b>${formatNumber(product.sevenDaySales)}</b></div>
        </div>
        <div class="quick-notes">
          ${renderQuickNotesForProduct(product)}
        </div>
      </div>
    </div>
    <div class="card-body">
      <div class="info-columns">
        <div class="info-column">
          <section class="info-section">
            <h3>适合人群</h3>
            <ul>${listItems(product.audience)}</ul>
          </section>
          <section class="info-section">
            <h3>核心卖点</h3>
            <ul>${listItems(product.sellingPoints)}</ul>
          </section>
        </div>
        <div class="info-column">
          <section class="info-section">
            <h3>版型效果</h3>
            <ul>${listItems(product.fit)}</ul>
          </section>
          <section class="info-section">
            <h3>搭配建议 / 注意点</h3>
            <ul>${listItems([...(product.styling || []), ...(product.cautions || [])])}</ul>
          </section>
        </div>
      </div>
      <section class="script-section">
        <div class="script-title-row">
          <h3>直播话术框架</h3>
        </div>
        <div class="script-grid">
          ${renderScriptBlocks(product.script)}
        </div>
      </section>
    </div>
  `;
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight, maxLines = 99) {
  const chars = String(text || "").split("");
  let line = "";
  let lines = [];

  for (const char of chars) {
    const testLine = line + char;
    if (ctx.measureText(testLine).width > maxWidth && line) {
      lines.push(line);
      line = char;
    } else {
      line = testLine;
    }
  }
  if (line) lines.push(line);

  if (lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    lines[maxLines - 1] = `${lines[maxLines - 1].slice(0, -1)}...`;
  }

  lines.forEach((row, index) => ctx.fillText(row, x, y + index * lineHeight));
  return y + lines.length * lineHeight;
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawSection(ctx, title, items, x, y, width, options = {}) {
  ctx.fillStyle = "#315c54";
  ctx.font = "800 32px Microsoft YaHei, Arial";
  ctx.fillText(title, x, y);
  y += 42;

  ctx.font = "400 25px Microsoft YaHei, Arial";
  const bulletColor = options.bulletColor || "#a46a43";

  (items || []).forEach((item) => {
    ctx.fillStyle = bulletColor;
    ctx.beginPath();
    ctx.arc(x + 8, y - 9, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#3c3731";
    y = wrapText(ctx, item, x + 24, y, width - 24, 36, options.maxLines || 3) + 12;
  });
  return y;
}

function measureWrappedText(ctx, text, maxWidth, lineHeight, maxLines = 99) {
  const chars = String(text || "").split("");
  let line = "";
  let lines = [];

  for (const char of chars) {
    const testLine = line + char;
    if (ctx.measureText(testLine).width > maxWidth && line) {
      lines.push(line);
      line = char;
    } else {
      line = testLine;
    }
  }
  if (line) lines.push(line);
  lines = lines.slice(0, maxLines);
  return Math.max(lineHeight, lines.length * lineHeight);
}

function measureScriptBlock(ctx, block, width) {
  let height = 72;
  ctx.font = "400 21px Microsoft YaHei, Arial";
  (block.lines || []).forEach((line) => {
    height += measureWrappedText(ctx, line, width - 70, 30) + 8;
  });
  return Math.max(145, height + 24);
}

function drawScriptBlock(ctx, block, x, y, width, height) {
  ctx.fillStyle = "#ffffff";
  roundRect(ctx, x, y, width, height, 10);
  ctx.fill();
  ctx.strokeStyle = "#ded8cf";
  ctx.stroke();

  ctx.fillStyle = "#a46a43";
  ctx.font = "800 24px Microsoft YaHei, Arial";
  ctx.fillText(block.title, x + 18, y + 34);

  let textY = y + 70;
  ctx.font = "400 21px Microsoft YaHei, Arial";
  (block.lines || []).forEach((line) => {
    ctx.fillStyle = "#3c3731";
    ctx.fillText("•", x + 20, textY);
    textY = wrapText(ctx, line, x + 48, textY - 2, width - 70, 30) + 8;
  });
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => resolve(img);
    img.onerror = reject;
    setTimeout(() => reject(new Error(`图片加载超时：${src}`)), 8000);
    img.src = src;
  });
}

function drawContainImage(ctx, img, x, y, w, h) {
  const scale = Math.min(w / img.width, h / img.height);
  const dw = img.width * scale;
  const dh = img.height * scale;
  ctx.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
}

function drawImagePlaceholder(ctx, x, y, w, h, text = "商品图加载失败") {
  ctx.fillStyle = "#f4efe7";
  roundRect(ctx, x, y, w, h, 12);
  ctx.fill();
  ctx.strokeStyle = "#d8cfc3";
  ctx.stroke();
  ctx.fillStyle = "#726b63";
  ctx.font = "700 26px Microsoft YaHei, Arial";
  ctx.fillText(text, x + 42, y + h / 2);
}

function showImagePreview(blob, filename) {
  if (latestPreviewUrl) {
    URL.revokeObjectURL(latestPreviewUrl);
  }
  latestPreviewUrl = URL.createObjectURL(blob);

  let preview = document.querySelector("#downloadPreview");
  if (!preview) {
    preview = document.createElement("div");
    preview.id = "downloadPreview";
    preview.className = "download-preview";
    preview.innerHTML = `
      <div class="download-preview-panel" role="dialog" aria-modal="true" aria-label="商品卡图片预览">
        <div class="download-preview-head">
          <strong>商品卡已生成</strong>
          <button class="download-preview-close" type="button" aria-label="关闭预览">关闭</button>
        </div>
        <p>手机端如果没有自动下载，请长按下面图片保存到相册；电脑端可以右键另存为。</p>
        <a class="download-preview-open" target="_blank" rel="noopener">打开原图</a>
        <div class="download-preview-scroll">
          <img alt="商品卡图片预览" />
        </div>
      </div>
    `;
    document.body.appendChild(preview);
    preview.addEventListener("click", (event) => {
      if (event.target === preview || event.target.closest(".download-preview-close")) {
        preview.classList.remove("is-visible");
      }
    });
  }

  const image = preview.querySelector("img");
  const openLink = preview.querySelector(".download-preview-open");
  image.src = latestPreviewUrl;
  openLink.href = latestPreviewUrl;
  openLink.download = filename;
  preview.classList.add("is-visible");
}

async function downloadCard(product) {
  const canvas = document.createElement("canvas");
  canvas.width = 1440;
  canvas.height = 22000;
  const ctx = canvas.getContext("2d");
  const img = await loadImage(product.image).catch((error) => {
    console.warn(error);
    return null;
  });

  ctx.fillStyle = "#f6f4ef";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#ffffff";
  roundRect(ctx, 54, 54, 1332, canvas.height - 108, 18);
  ctx.fill();

  ctx.fillStyle = "#315c54";
  ctx.font = "800 30px Microsoft YaHei, Arial";
  ctx.fillText("IHIMI 兼职主播商品卡", 92, 116);

  ctx.fillStyle = "#27231f";
  ctx.font = "800 48px Microsoft YaHei, Arial";
  wrapText(ctx, product.name, 92, 190, 760, 62, 3);
  ctx.fillStyle = "#315c54";
  ctx.font = "800 28px Microsoft YaHei, Arial";
  ctx.fillText(product.code, 92, 390);

  ctx.fillStyle = "#f4efe7";
  roundRect(ctx, 900, 150, 410, 410, 12);
  ctx.fill();
  if (img) {
    drawContainImage(ctx, img, 918, 168, 374, 374);
  } else {
    drawImagePlaceholder(ctx, 918, 168, 374, 374);
  }

  ctx.fillStyle = "#fffdfa";
  ctx.strokeStyle = "#d8cfc3";
  roundRect(ctx, 900, 586, 410, 178, 12);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#a46a43";
  ctx.font = "800 24px Microsoft YaHei, Arial";
  ctx.fillText("面料信息", 922, 628);
  ctx.fillStyle = "#27231f";
  ctx.font = "800 20px Microsoft YaHei, Arial";
  wrapText(ctx, product.fabric?.main || "系统暂未返回材质成份", 922, 662, 366, 25, 4);

  const metrics = [
    ["直播价", money(product.price)],
    ["品类", product.category],
    ["库存", formatNumber(product.stock)],
    ["近7天销量", formatNumber(product.sevenDaySales)],
  ];
  metrics.forEach(([label, value], index) => {
    const x = 92 + index * 194;
    ctx.fillStyle = "#fffdfa";
    ctx.strokeStyle = "#ded8cf";
    roundRect(ctx, x, 454, 172, 106, 10);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#726b63";
    ctx.font = "400 22px Microsoft YaHei, Arial";
    ctx.fillText(label, x + 18, 489);
    ctx.fillStyle = "#27231f";
    ctx.font = "800 32px Microsoft YaHei, Arial";
    ctx.fillText(value, x + 18, 535);
  });

  (product.quickNotes || []).forEach(([label, text], index) => {
    const col = index % 2;
    const row = Math.floor(index / 2);
    const x = 900 + col * 205;
    const yNote = 792 + row * 102;
    ctx.fillStyle = "#fbfaf7";
    ctx.strokeStyle = "#ded8cf";
    roundRect(ctx, x, yNote, 190, 84, 10);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#a46a43";
    ctx.font = "800 20px Microsoft YaHei, Arial";
    ctx.fillText(label, x + 14, yNote + 30);
    if (label === "库存信息") {
      const sizes = (product.sizeStock || []).slice(0, 5);
      const cellW = 160 / Math.max(sizes.length, 1);
      ctx.textAlign = "center";
      sizes.forEach(([size], sizeIndex) => {
        ctx.fillStyle = "#27231f";
        ctx.font = "800 14px Microsoft YaHei, Arial";
        ctx.fillText(size, x + 14 + cellW * sizeIndex + cellW / 2, yNote + 55);
      });
      sizes.forEach(([, qty], sizeIndex) => {
        ctx.fillStyle = "#3c3731";
        ctx.font = "700 16px Microsoft YaHei, Arial";
        ctx.fillText(formatNumber(qty), x + 14 + cellW * sizeIndex + cellW / 2, yNote + 78);
      });
      ctx.textAlign = "left";
    } else {
      ctx.fillStyle = "#3c3731";
      ctx.font = "400 18px Microsoft YaHei, Arial";
      wrapText(ctx, text, x + 14, yNote + 57, 160, 24, 2);
    }
  });

  ctx.strokeStyle = "#ded8cf";
  ctx.beginPath();
  ctx.moveTo(92, 970);
  ctx.lineTo(1310, 970);
  ctx.stroke();

  ctx.fillStyle = "#a46a43";
  ctx.font = "800 30px Microsoft YaHei, Arial";
  ctx.fillText("一句话定位", 92, 1040);
  ctx.fillStyle = "#3c3731";
  ctx.font = "400 28px Microsoft YaHei, Arial";
  let y = wrapText(ctx, product.positioning, 92, 1088, 1218, 42, 3) + 34;

  const leftX = 92;
  const rightX = 725;
  const colW = 585;
  let leftY = y;
  let rightY = y;
  leftY = drawSection(ctx, "适合人群", product.audience, leftX, leftY, colW);
  leftY += 26;
  leftY = drawSection(ctx, "核心卖点", (product.sellingPoints || []).slice(0, 4), leftX, leftY, colW, { maxLines: 2 });
  rightY = drawSection(ctx, "版型效果", product.fit, rightX, rightY, colW);
  rightY += 26;
  rightY = drawSection(ctx, "搭配建议", product.styling, rightX, rightY, colW);
  y = Math.max(leftY, rightY) + 24;

  ctx.strokeStyle = "#ded8cf";
  ctx.beginPath();
  ctx.moveTo(92, y);
  ctx.lineTo(1310, y);
  ctx.stroke();
  y += 72;
  y = drawSection(ctx, "注意点", product.cautions, 92, y, 1218, { bulletColor: "#d95f3f", maxLines: 2 }) + 18;

  const scriptStartY = y;
  ctx.fillStyle = "#fffdfa";
  roundRect(ctx, 92, scriptStartY, 1218, 100, 14);
  ctx.fill();
  ctx.fillStyle = "#315c54";
  ctx.font = "800 34px Microsoft YaHei, Arial";
  ctx.fillText("直播话术框架", 126, y + 58);

  const scriptColW = 548;
  const scriptGapX = 48;
  const scriptGapY = 20;
  const scriptX = [126, 126 + scriptColW + scriptGapX];
  let scriptY = y + 92;
  const scriptBlocks = product.script || [];
  for (let index = 0; index < scriptBlocks.length; index += 2) {
    const leftBlock = scriptBlocks[index];
    const rightBlock = scriptBlocks[index + 1];
    const rowHeight = Math.max(
      leftBlock ? measureScriptBlock(ctx, leftBlock, scriptColW) : 0,
      rightBlock ? measureScriptBlock(ctx, rightBlock, scriptColW) : 0,
    );
    if (leftBlock) {
      drawScriptBlock(ctx, leftBlock, scriptX[0], scriptY, scriptColW, rowHeight);
    }
    if (rightBlock) {
      drawScriptBlock(ctx, rightBlock, scriptX[1], scriptY, scriptColW, rowHeight);
    }
    scriptY += rowHeight + scriptGapY;
  }
  const scriptEndY = scriptY + 28;
  ctx.strokeStyle = "#ded8cf";
  roundRect(ctx, 92, scriptStartY, 1218, scriptEndY - scriptStartY, 14);
  ctx.stroke();

  ctx.fillStyle = "#726b63";
  ctx.font = "400 22px Microsoft YaHei, Arial";
  const footerY = scriptEndY + 48;
  ctx.fillText("IHIMI 产品商品卡", 92, footerY);

  const finalHeight = Math.min(canvas.height, Math.ceil(footerY + 120));
  const outputCanvas = document.createElement("canvas");
  outputCanvas.width = canvas.width;
  outputCanvas.height = finalHeight;
  outputCanvas.getContext("2d").drawImage(canvas, 0, 0);

  outputCanvas.toBlob((blob) => {
    if (!blob) {
      downloadStatus.textContent = "生成失败：浏览器未能导出图片";
      return;
    }
    const filename = `${product.code}-兼职主播商品卡.png`;
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.download = filename;
    link.href = url;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    showImagePreview(blob, filename);
    downloadStatus.textContent = "已生成高清 PNG；手机端可长按预览图保存";
  }, "image/png");
}

filterRow.addEventListener("click", (event) => {
  const button = event.target.closest(".filter-button");
  if (!button) return;
  activeFilter = button.dataset.filter;
  renderFilters();
  renderProductList();
});

productList.addEventListener("click", (event) => {
  const item = event.target.closest(".product-item");
  if (!item) return;
  activeProduct = products.find((product) => product.id === item.dataset.id);
  renderProductList();
  renderCard(activeProduct);
});

searchInput.addEventListener("input", renderProductList);

downloadCardBtn.addEventListener("click", () => {
  if (!activeProduct) return;
  downloadStatus.textContent = "正在生成...";
  downloadCard(activeProduct).catch((error) => {
    console.error(error);
    downloadStatus.textContent = `生成失败：${error.message || "请刷新后重试"}`;
    alert("下载失败，请确认商品图片可以正常显示。");
  });
});

function setupDirectLinkBar() {
  let isFramed = false;
  try {
    isFramed = window.self !== window.top;
  } catch (error) {
    isFramed = true;
  }

  const isLocal = ["127.0.0.1", "localhost"].includes(window.location.hostname);
  if ((!isFramed && !isLocal) || !directLinkBar || !directLinkInput) return;
  directLinkInput.value = PERMANENT_MOBILE_LINK;
  directLinkBar.hidden = false;

  copyDirectLinkBtn?.addEventListener("click", async () => {
    directLinkInput.focus();
    directLinkInput.select();
    try {
      await navigator.clipboard.writeText(directLinkInput.value);
      directLinkStatus.textContent = "已复制直达链接";
    } catch (error) {
      directLinkStatus.textContent = "已选中链接，可长按复制";
    }
  });
}

setupDirectLinkBar();
renderFilters();
renderProductList();
renderCard(activeProduct);
